    const id = genId('slot');
    const slot = {
      id,
      propertyId,
      type: slotInput.type, // 'private' or 'openHouse'
      startTime: slotInput.startTime,
      endTime: slotInput.endTime,
      capacity: slotInput.capacity || 1,
      status: 'available',
      publishedAt: nowIso(),
