    return id;
}
function addTimesheetEntry(crewMemberId, workOrderId, hours, date, rate) { /* req-7, req-12 */
    const id = genId('timesheet');
    timesheets.set(id, { id, crewMemberId, workOrderId, hours, date, rate, createdAt: nowIso() });
    return id;
}
