        // threshold: 40 hours per week by default
        const threshold = 40;
        if (entry.hours <= threshold) {
            pr.regularHours += entry.hours;
        } else {
            pr.overtimeHours += entry.hours - threshold;
            pr.regularHours += threshold;
        }
    }
